    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
    F0 = F0 - F9;
    R1 = DM(19, I7);
    F0 = F0 * F1;
    F0 = F9 + F0;
    JUMP _za_s3;
_za_s2:
    R3 = 0x3F000000;
    F1 = F1 * F3;                                       // contour = Sine(c + shape * 0.5f)
    R0 = DM(16, I7);
    F0 = F0 + F1;
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
_za_s3:
    R1 = DM(22, I7);
    R2 = DM(23, I7);
    F2 = F1 + F2;                                       // (ramp_down * (offset + discontinuity) - offset) * contour
    R3 = DM(21, I7);
    F2 = F3 * F2;
    F2 = F2 - F1;
    F0 = F2 * F0;
    R1 = DM(15, I7);
    F0 = F0 - F1;                                       // discontinuity = after - before
    R2 = DM(14, I7);
    R3 = 0x3F000000;
    F3 = F3 * F2;                                       // ThisBlepSample(reset_time)
    F3 = F3 * F2;
    F3 = F0 * F3;
    F12 = F12 + F3;                                     // this_sample += discontinuity * ..
    F4 = F9 - F2;                                       // NextBlepSample(reset_time)
    R3 = 0xBF000000;
    F3 = F3 * F4;
    F3 = F3 * F4;
    F3 = F0 * F3;
    F13 = F13 + F3;                                     // next_sample += discontinuity * ..
    R1 = DM(13, I7);
    F1 = F2 * F1;                                       // formant_phase_ = reset_time * f1
    DM(18, I7) = R1;
    COMP(F11, F9);                                      // carrier_phase_ > 1.0f
    IF LE JUMP _zk_cw;
    R1 = 0x3F000000;
    F11 = F10 * F1;                                     // carrier_phase_ = discontinuity_phase_ * 0.5f
    JUMP _zk_cw;
_zk_nr:
    R1 = DM(18, I7);
    F1 = F1 + F2;                                       // formant_phase_ += f1
    COMP(F1, F9);                                       // formant_phase_ >= 1.0f
    IF LT JUMP _zk_fw;
    F1 = F1 - F9;
_zk_fw:
    DM(18, I7) = R1;
_zk_cw:
    COMP(F11, F9);                                      // carrier_phase_ >= 1.0f
    IF LT JUMP _zk_cx;
    F11 = F11 - F9;
_zk_cx:
    DM(16, I7) = R11;
    DM(17, I7) = R10;
    R1 = DM(6, I1);
    R2 = DM(9, I7);
    F1 = F1 + F2;                                       // carrier_shape_modulation.Next()
    DM(6, I1) = R1;
    DM(19, I7) = R1;
    R1 = DM(7, I1);
    R2 = DM(10, I7);
    F1 = F1 + F2;                                       // mode_modulation.Next()
    DM(7, I1) = R1;
    DM(20, I7) = R1;
    R0 = DM(17, I7);
    R1 = 0x3F000000;
    F0 = F1 * F0;                                       // ramp_down = 0.5f * (1.0f + Sine(0.5f * d + 0.25f))
    R1 = 0x3E800000;
    F0 = F0 + F1;
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
    F0 = F9 + F0;
    R1 = 0x3F000000;
    F0 = F1 * F0;
    DM(21, I7) = R0;
    R1 = DM(20, I7);
    R3 = 0x3EAA7EFA;
    COMP(F1, F3);                                       // mode < 0.333f
    IF GE JUMP _zn_m1;
    DM(22, I7) = R9;                                    // offset = 1.0f
    R5 = 0x3FC00000;
    F6 = F1 * F5;                                       // phase_shift = 0.25f + mode * 1.50f
    R3 = 0x3E800000;
    F4 = F3 + F6;
    JUMP _zn_ps;
_zn_m1:
    R5 = 0x3EA8F5C3;
    F6 = F1 - F5;                                       // phase_shift = 0.7495f - (mode - 0.33f) * 0.75f
    R5 = 0x3F400000;
    F6 = F6 * F5;
    R5 = 0x3F3FDF3B;
    F4 = F5 - F6;
    R3 = 0x3F2A7EFA;
    COMP(F1, F3);                                       // mode < 0.666f
    IF GE JUMP _zn_m2;
    DM(23, I7) = R4;                                    // (phase_shift)
    R1 = TRUNC F4;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F4 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
    F0 = -F0;                                           // offset = -Sine(phase_shift)
    DM(22, I7) = R0;
    R4 = DM(23, I7);
    JUMP _zn_ps;
_zn_m2:
    R0 = 0x3A83126F;
    DM(22, I7) = R0;                                    // offset = 0.001f
_zn_ps:
    R0 = DM(18, I7);
    F0 = F0 + F4;                                       // discontinuity = Sine(f + phase_shift)
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
    DM(23, I7) = R0;
    R1 = DM(19, I7);
    R3 = 0x3F000000;
    COMP(F1, F3);                                       // shape < 0.5f
    IF GE JUMP _zn_s2;
    R3 = 0x40000000;
    F1 = F1 * F3;                                       // shape *= 2.0f
    DM(19, I7) = R1;
    R0 = DM(16, I7);
    R3 = 0x3F000000;
    COMP(F0, F3);                                       // c >= 0.5f: ramp_down *= shape
    IF LT JUMP _zn_s1;
    R4 = DM(21, I7);
    F4 = F4 * F1;
    DM(21, I7) = R4;
_zn_s1:
    R3 = 0x3E800000;
    F0 = F0 + F3;                                       // contour = 1.0f + (Sine(c + 0.25f) - 1.0f) * shape
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
    F0 = F0 - F9;
    R1 = DM(19, I7);
    F0 = F0 * F1;
    F0 = F9 + F0;
    JUMP _zn_s3;
_zn_s2:
    R3 = 0x3F000000;
    F1 = F1 * F3;                                       // contour = Sine(c + shape * 0.5f)
    R0 = DM(16, I7);
    F0 = F0 + F1;
    R1 = TRUNC F0;                                      // Sine: index -= itof_nonneg((int)index)
    R1 = R15 OR R1;
    F1 = F1 - F15;
    F1 = F0 - F1;
    R2 = 0x44000000;
    F1 = F1 * F2;                                       // index *= 512.0f
    R2 = TRUNC F1;                                      // index_integral
    R3 = R15 OR R2;
    R2 = LSHIFT R2 BY 2;
    .NOCOMPRESS;
    R2 = R2 + R14;                                      // (48-bit: the compressed integer add is not in stock code)
    .COMPRESS;
    I4 = R2;
    F3 = F3 - F15;
    F3 = F1 - F3;                                       // index_fractional
    R1 = DM(I4, M5);                                    // a
    R2 = DM(1, I4);                                     // b
    F2 = F2 - F1;                                       // a + (b - a) * index_fractional
    F2 = F2 * F3;
    F0 = F1 + F2;
_zn_s3:
    R1 = DM(22, I7);
    R2 = DM(23, I7);
    F2 = F1 + F2;                                       // (ramp_down * (offset + discontinuity) - offset) * contour
    R3 = DM(21, I7);
    F2 = F3 * F2;
    F2 = F2 - F1;
    F0 = F2 * F0;
    F13 = F13 + F0;                                     // next_sample += ..
    DM(I0, M6) = R12;                                   // *out++ = this_sample
    R0 = DM(11, I7);
    R1 = 1;
    R0 = R0 - R1;
    DM(11, I7) = R0;
    IF NE JUMP _zk_loop;
_zk_done:
    DM(0, I1) = R11;
    DM(1, I1) = R10;
    R0 = DM(18, I7);
    DM(2, I1) = R0;
    DM(3, I1) = R13;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,23)(NW);
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

grain_hp_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I4 = R4;                                            // f
    I0 = R8;                                            // x
    I1 = R12;                                           // y
    R5 = DM(0, I4);                                     // g_
    R6 = DM(1, I4);                                     // gi_
    R7 = DM(2, I4);                                     // state_
    R8 = DM(1, I6);                                     // size
    R0 = 0;
    COMP(R8, R0);
    IF LE JUMP _ghp_done;
    COMP(R12, R0);
    IF EQ JUMP _ghp_plain;
    LCNTR = R8, DO _ghp_e0 UNTIL LCE;
    R0 = DM(I0, M5);                                    // in = x[i] + y[i]
    R1 = DM(I1, M6);
    F0 = F0 + F1;
    F1 = F5 * F0;                                       // lp = (g_ * in + state_) * gi_
    F1 = F1 + F7;
    F1 = F1 * F6;
    F2 = F0 - F1;                                       // state_ = g_ * (in - lp) + lp
    F3 = F5 * F2;
    F7 = F3 + F1;
_ghp_e0:
    DM(I0, M6) = R2;                                    // in - lp
    JUMP _ghp_done;
_ghp_plain:
    LCNTR = R8, DO _ghp_e1 UNTIL LCE;
    R0 = DM(I0, M5);                                    // in = x[i]
    F1 = F5 * F0;                                       // lp = (g_ * in + state_) * gi_
    F1 = F1 + F7;
    F1 = F1 * F6;
    F2 = F0 - F1;                                       // state_ = g_ * (in - lp) + lp
    F3 = F5 * F2;
    F7 = F3 + F1;
_ghp_e1:
    DM(I0, M6) = R2;                                    // in - lp
_ghp_done:
    DM(2, I4) = R7;
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
